1	"use client";
2	
3	import { useEffect, useRef, useState } from "react";
4	import type { SendAttachment, SendPayload } from "@/lib/mail/types";
5	import { safeHtml } from "@/lib/mail/render";
6	import type { SignaturePlacement } from "@/lib/mail/signature";
7	import { prepareComposedBody, plainTextFromEditor } from "./compose-html";
8	import { addRecipients, extractAddress, isValidEmail, parseRecipientInput, recipientsToField } from "./recipients";
9	import {
10	  IMAGE_SIZE_PRESETS,
11	  imagePresetLabel,
12	  imageStyleForPreset,
13	  imageWidthAttrForPreset,
14	  type ImageSizePreset,
15	} from "./compose-image-size";
16	import { Icon } from "./util";
17	
18	export type ComposeDraft = {
19	  mode: "new" | "reply" | "replyAll" | "forward";
20	  to: string;
21	  cc: string;
22	  subject: string;
23	  body: string; // plaintext the user edits
24	  quotedHtml?: string; // quoted original, appended below the reply
25	  signature?: string; // plain-text signature / fallback for the text part
26	  signatureHtml?: string; // sanitized rich-signature HTML for the HTML part
27	  signaturePlacement?: SignaturePlacement; // where the signature sits relative to quoted text
28	  inReplyToUid?: number;
29	  replyFolder?: string;
30	  /** The mailbox to send from. The composer lives at the shell level now, so the
31	   *  active mailbox rides along on the draft instead of being read from the page. */
32	  sendMailboxAddress?: string;
33	};
34	
35	// Attachment limits — mirrored server-side (the server re-validates and is the
36	// source of truth). Kept here only for fast, friendly client-side feedback.
37	const MAX_ATTACHMENTS = 10;
38	const MAX_ATTACHMENTS_TOTAL_BYTES = 20 * 1024 * 1024; // 20 MB
39	
40	// A file the user has attached, already read into base64 in the browser.
41	type Attachment = {
42	  id: string;
43	  filename: string;
44	  contentType: string;
45	  size: number; // decoded byte size
46	  contentBase64: string;
47	};
48	
49	function formatBytes(bytes: number): string {
50	  if (bytes < 1024) return `${bytes} B`;
51	  const kb = bytes / 1024;
52	  if (kb < 1024) return `${kb < 10 ? kb.toFixed(1) : Math.round(kb)} KB`;
53	  const mb = kb / 1024;
54	  return `${mb < 10 ? mb.toFixed(1) : Math.round(mb)} MB`;
55	}
56	
57	// Read a File into raw base64 (stripping the "data:*;base64," prefix).
58	function readFileBase64(file: File): Promise<string> {
59	  return new Promise((resolve, reject) => {
60	    const reader = new FileReader();
61	    reader.onerror = () => reject(new Error(`Could not read ${file.name}.`));
62	    reader.onload = () => {
63	      const result = String(reader.result || "");
64	      const comma = result.indexOf(",");
65	      resolve(comma >= 0 ? result.slice(comma + 1) : result);
66	    };
67	    reader.readAsDataURL(file);
68	  });
69	}
70	
71	export function Composer({
72	  draft,
73	  minimized = false,
74	  onClose,
75	  onMinimize,
76	  onRestore,
77	  onSend,
78	}: {
79	  draft: ComposeDraft;
80	  /** When true, the full panel is hidden (but kept mounted so the draft, editor
81	   *  DOM and attachments survive) and a small docked bar is shown instead. */
82	  minimized?: boolean;
83	  onClose: () => void;
84	  onMinimize: () => void;
85	  onRestore: () => void;
86	  onSend: (payload: SendPayload, mailboxAddress?: string) => Promise<void>;
87	}) {
88	  // Recipients are chip inputs: `*Chips` hold committed addresses, `*Input` holds
89	  // what's being typed (also the home for tokens that weren't valid addresses).
90	  const [toChips, setToChips] = useState<string[]>(() => parseRecipientInput(draft.to).valid);
91	  const [toInput, setToInput] = useState("");
92	  const [ccChips, setCcChips] = useState<string[]>(() => parseRecipientInput(draft.cc).valid);
93	  const [ccInput, setCcInput] = useState("");
94	  const [showCc, setShowCc] = useState(!!draft.cc);
95	  const [subject, setSubject] = useState(draft.subject);
96	  const [sending, setSending] = useState(false);
97	  const [error, setError] = useState<string | null>(null);
98	  const [attachments, setAttachments] = useState<Attachment[]>([]);
99	  const [reading, setReading] = useState(false);
100	  const [dragging, setDragging] = useState(false);
101	  // The rich editor is a contentEditable region (inherently ref-driven). We
102	  // track only whether it is EMPTY so the placeholder can show — the authoritative
103	  // HTML is always read from the ref at submit time, never from React state, so
104	  // there is no controlled/uncontrolled reset to lose the customer's draft.
105	  const [editorEmpty, setEditorEmpty] = useState(!draft.body.trim());
106	  // The floating size toolbar for a clicked inline image (viewport rect of the img).
107	  const [imgRect, setImgRect] = useState<DOMRect | null>(null);
108	
109	  const fileInputRef = useRef<HTMLInputElement>(null);
110	  const imageInputRef = useRef<HTMLInputElement>(null);
111	  const editorRef = useRef<HTMLDivElement>(null);
112	  const toInputRef = useRef<HTMLInputElement>(null);
113	  const selectedImgRef = useRef<HTMLImageElement | null>(null);
114	  const dragDepth = useRef(0); // ignore nested dragenter/dragleave events
115	
116	  // Seed the editor once from the draft's plaintext body (escaped, newlines →
117	  // <br>). Reply/forward drafts start with blank lines; "new" starts empty.
118	  useEffect(() => {
119	    const el = editorRef.current;
120	    if (!el) return;
121	    const seed = draft.body
122	      ? draft.body.replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/\n/g, "<br>")
123	      : "";
124	    el.innerHTML = seed;
125	    setEditorEmpty(!el.textContent?.trim() && !el.querySelector("img"));
126	    // Seed exactly once on mount — the ref is stable and never re-seeded.
127	    // eslint-disable-next-line react-hooks/exhaustive-deps
128	  }, []);
129	
130	  // Focus management: on open (and on every restore from minimized) put the caret
131	  // where the customer will type first — the To field for new/forward, the body
132	  // for a reply where the recipient is already filled in.
133	  useEffect(() => {
134	    if (minimized) return;
135	    const t = setTimeout(() => {
136	      if (draft.mode === "reply" || draft.mode === "replyAll") editorRef.current?.focus();
137	      else toInputRef.current?.focus();
138	    }, 0);
139	    return () => clearTimeout(t);
140	    // eslint-disable-next-line react-hooks/exhaustive-deps
141	  }, [minimized]);
142	
143	  useEffect(() => {
144	    const onKey = (e: KeyboardEvent) => {
145	      // Esc minimizes (non-destructive — keeps the draft) rather than discarding.
146	      if (e.key === "Escape" && !sending && !minimized) {
147	        e.preventDefault();
148	        clearImgSelection();
149	        onMinimize();
150	      }
151	      if ((e.metaKey || e.ctrlKey) && e.key === "Enter" && !minimized) void submit();
152	    };
153	    window.addEventListener("keydown", onKey);
154	    return () => window.removeEventListener("keydown", onKey);
155	    // eslint-disable-next-line react-hooks/exhaustive-deps
156	  }, [toChips, ccChips, toInput, ccInput, subject, sending, attachments, minimized]);
157	
158	  function syncEmpty() {
159	    const el = editorRef.current;
160	    setEditorEmpty(!!el && !el.textContent?.trim() && !el.querySelector("img"));
161	  }
162	
163	  /* ---- Recipient chips -------------------------------------------------- */
164	  function commitTo(raw: string) {
165	    const { chips, invalid } = addRecipients(toChips, raw);
166	    setToChips(chips);
167	    setToInput(invalid.join(", "));
168	    setError(invalid.length ? `Not a valid email: ${invalid.join(", ")}` : null);
169	  }
170	  function commitCc(raw: string) {
171	    const { chips, invalid } = addRecipients(ccChips, raw);
172	    setCcChips(chips);
173	    setCcInput(invalid.join(", "));
174	    setError(invalid.length ? `Not a valid email: ${invalid.join(", ")}` : null);
175	  }
176	
177	  /* ---- Inline image sizing ---------------------------------------------- */
178	  function clearImgSelection() {
179	    selectedImgRef.current?.classList.remove("nx-img-selected");
180	    selectedImgRef.current = null;
181	    setImgRect(null);
182	  }
183	
184	  function onEditorClick(e: React.MouseEvent) {
185	    const t = e.target as HTMLElement | null;
186	    if (t && t.tagName === "IMG") {
187	      if (selectedImgRef.current && selectedImgRef.current !== t) {
188	        selectedImgRef.current.classList.remove("nx-img-selected");
189	      }
190	      const img = t as HTMLImageElement;
191	      img.classList.add("nx-img-selected");
192	      selectedImgRef.current = img;
193	      setImgRect(img.getBoundingClientRect());
194	    } else {
195	      clearImgSelection();
196	    }
197	  }
198	
199	  function applyImagePreset(preset: ImageSizePreset) {
200	    const img = selectedImgRef.current;
201	    if (!img) return;
202	    img.setAttribute("style", imageStyleForPreset(preset));
203	    const w = imageWidthAttrForPreset(preset);
204	    if (w) img.setAttribute("width", w);
205	    else img.removeAttribute("width");
206	    setImgRect(img.getBoundingClientRect());
207	    syncEmpty();
208	  }
209	
210	  // Insert a pasted/embedded image as a data: URI at the caret. It is converted
211	  // to an inline cid attachment by prepareComposedBody() at send time.
212	  function insertInlineImage(file: File) {
213	    if (file.size > MAX_ATTACHMENTS_TOTAL_BYTES) {
214	      setError(`Images must be under ${formatBytes(MAX_ATTACHMENTS_TOTAL_BYTES)}.`);
215	      return;
216	    }
217	    const reader = new FileReader();
218	    reader.onload = () => {
219	      const url = String(reader.result || "");
220	      if (!url.startsWith("data:image/")) return;
221	      editorRef.current?.focus();
222	      try {
223	        document.execCommand("insertImage", false, url);
224	      } catch {
225	        /* ignore — nothing inserted */
226	      }
227	      syncEmpty();
228	    };
229	    reader.readAsDataURL(file);
230	  }
231	
232	  // Apply a formatting command to the current selection inside the editor.
233	  function format(command: string, value?: string) {
234	    editorRef.current?.focus();
235	    try {
236	      document.execCommand(command, false, value);
237	    } catch {
238	      /* execCommand is unavailable in some embeddings — degrade to plain text */
239	    }
240	    syncEmpty();
241	  }
242	
243	  // Paste: images go inline; everything else keeps the browser's formatted paste
244	  // (sanitised at send). Formatted copy-paste is therefore preserved reasonably.
245	  function onEditorPaste(e: React.ClipboardEvent) {
246	    const items = Array.from(e.clipboardData?.items ?? []);
247	    const image = items.find((i) => i.kind === "file" && i.type.startsWith("image/"));
248	    if (image) {
249	      const file = image.getAsFile();
250	      if (file) {
251	        e.preventDefault();
252	        setError(null);
253	        insertInlineImage(file);
254	      }
255	    }
256	  }
257	
258	  const totalBytes = attachments.reduce((n, a) => n + a.size, 0);
259	
260	  // Read a batch of picked/dropped files, enforcing count + total-size caps.
261	  async function addFiles(files: FileList | File[]) {
262	    const list = Array.from(files);
263	    if (list.length === 0) return;
264	    setError(null);
265	
266	    let count = attachments.length;
267	    let running = totalBytes;
268	    const next: Attachment[] = [];
269	    setReading(true);
270	    try {
271	      for (const file of list) {
272	        if (count >= MAX_ATTACHMENTS) {
273	          setError(`You can attach up to ${MAX_ATTACHMENTS} files.`);
274	          break;
275	        }
276	        if (running + file.size > MAX_ATTACHMENTS_TOTAL_BYTES) {
277	          setError(`Attachments can total at most ${formatBytes(MAX_ATTACHMENTS_TOTAL_BYTES)}.`);
278	          break;
279	        }
280	        try {
281	          const contentBase64 = await readFileBase64(file);
282	          next.push({
283	            id: `${Date.now()}-${count}-${Math.random().toString(36).slice(2, 8)}`,
284	            filename: file.name || "attachment",
285	            contentType: file.type || "application/octet-stream",
286	            size: file.size,
287	            contentBase64,
288	          });
289	          count += 1;
290	          running += file.size;
291	        } catch (e) {
292	          setError(e instanceof Error ? e.message : "Could not read a file.");
293	        }
294	      }
295	      if (next.length) setAttachments((prev) => [...prev, ...next]);
296	    } finally {
297	      setReading(false);
298	    }
299	  }
300	
301	  function removeAttachment(id: string) {
302	    setAttachments((prev) => prev.filter((a) => a.id !== id));
303	    if (error) setError(null);
304	  }
305	
306	  function onDrop(e: React.DragEvent) {
307	    e.preventDefault();
308	    dragDepth.current = 0;
309	    setDragging(false);
310	    if (e.dataTransfer?.files?.length) void addFiles(e.dataTransfer.files);
311	  }
312	
313	  const title =
314	    draft.mode === "new" ? "New message" : draft.mode === "forward" ? "Forward" : "Reply";
315	
316	  async function submit() {
317	    if (sending || reading) return;
318	
319	    // Flush any half-typed recipients into chips before validating/sending.
320	    const finalTo = addRecipients(toChips, toInput).chips;
321	    const finalCc = addRecipients(ccChips, ccInput).chips;
322	    setToChips(finalTo);
323	    setToInput("");
324	    setCcChips(finalCc);
325	    setCcInput("");
326	
327	    if (finalTo.length === 0) {
328	      setError("Add at least one recipient.");
329	      return;
330	    }
331	    clearImgSelection();
332	    setError(null);
333	    setSending(true);
334	    try {
335	      const esc = (s: string) => s.replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;");
336	
337	      // Read the composed rich body straight from the editor DOM — never from
338	      // React state — then sanitise it and lift inline images out to cid:
339	      // attachments. `safeBody` is XSS-safe HTML; `inlineImages` are the
340	      // multipart/related parts the send path carries with matching Content-IDs.
341	      const rawHtml = editorRef.current?.innerHTML ?? "";
342	      const plainText = plainTextFromEditor(editorRef.current?.innerText ?? "");
343	      const { html: safeBody, images: inlineImages } = prepareComposedBody(rawHtml);
344	
345	      // Guard the combined attachment budget (files + inline images) before we
346	      // hand oversize data to the server. The server re-validates authoritatively.
347	      const inlineBytes = inlineImages.reduce((n, img) => n + Math.floor((img.contentBase64.length * 3) / 4), 0);
348	      if (totalBytes + inlineBytes > MAX_ATTACHMENTS_TOTAL_BYTES) {
349	        setError(`Message is too large — files and inline images must total under ${formatBytes(MAX_ATTACHMENTS_TOTAL_BYTES)}.`);
350	        setSending(false);
351	        return;
352	      }
353	
354	      // Signature: prefer the sanitized rich-HTML signature; fall back to the
355	      // legacy plain-text one. `signatureHtml` is already sanitized server-side,
356	      // but we re-sanitize here as defence in depth.
357	      const sigPlain = draft.signature?.trim();
358	      const sigRichRaw = draft.signatureHtml?.trim();
359	      const sigRich = sigRichRaw ? safeHtml(sigRichRaw) : "";
360	      const sigText = sigPlain ? `\n\n-- \n${sigPlain}` : "";
361	      const sigHtml = sigRich
362	        ? `<br><br><div class="nx-sig">${sigRich}</div>`
363	        : sigPlain
364	          ? `<br><div style="white-space:pre-wrap;font-family:-apple-system,Segoe UI,Roboto,sans-serif;font-size:13px;line-height:1.6;color:#64748b">-- <br>${esc(sigPlain)}</div>`
365	          : "";
366	
367	      const userDiv = `<div style="font-family:-apple-system,Segoe UI,Roboto,sans-serif;font-size:14px;line-height:1.6;color:#1e293b">${safeBody}</div>`;
368	      const quoteHtml = draft.quotedHtml
369	        ? `<br><blockquote style="margin:0 0 0 12px;padding-left:12px;border-left:3px solid #e2e8f0;color:#64748b">${draft.quotedHtml}</blockquote>`
370	        : "";
371	
372	      // Placement only matters when there IS a quote (replies/forwards). "above"
373	      // puts the signature between the reply and the quoted original; "below"
374	      // (default) puts it after everything.
375	      const above = draft.signaturePlacement === "above";
376	      const htmlBody = above ? userDiv + sigHtml + quoteHtml : userDiv + quoteHtml + sigHtml;
377	
378	      const outAttachments: SendAttachment[] = [
379	        ...attachments.map((a) => ({
380	          filename: a.filename,
381	          contentType: a.contentType,
382	          contentBase64: a.contentBase64,
383	        })),
384	        ...inlineImages.map((img) => ({
385	          filename: img.filename,
386	          contentType: img.contentType,
387	          contentBase64: img.contentBase64,
388	          cid: img.cid,
389	        })),
390	      ];
391	
392	      await onSend(
393	        {
394	          to: recipientsToField(finalTo),
395	          cc: finalCc.length ? recipientsToField(finalCc) : undefined,
396	          subject: subject.trim() || "(no subject)",
397	          text: plainText + sigText,
398	          html: htmlBody,
399	          attachments: outAttachments.length ? outAttachments : undefined,
400	          inReplyToUid: draft.inReplyToUid,
401	          replyFolder: draft.replyFolder,
402	        },
403	        draft.sendMailboxAddress,
404	      );
405	      onClose();
406	    } catch (e) {
407	      setError(e instanceof Error ? e.message : "Failed to send. Please try again.");
408	      setSending(false);
409	    }
410	  }
411	
412	  const hasRecipient = toChips.length > 0 || isValidEmail(extractAddress(toInput));
413	
414	  // Minimized: hide the full panel (keeping it mounted so the draft, editor DOM
415	  // and attachments all persist) and show a compact docked bar.
416	  const dockLabel = subject.trim() || title;
417	
418	  return (
419	    <>
420	      {/* Full composer. `pointer-events-none` on the fixed wrapper lets the page
421	          behind stay usable (so you can navigate while a draft is open); only the
422	          panel itself captures clicks. The wrapper carries NO filter/transform, so
423	          `fixed` resolves to the true viewport (the composer is portalled to
424	          <body>), keeping it visible no matter how far the page is scrolled. */}
425	      <div
426	        className={`fixed inset-0 z-[55] flex items-center justify-center p-0 sm:p-4 ${minimized ? "hidden" : ""} pointer-events-none`}
427	        role="dialog"
428	        aria-label={title}
429	      >
430	        {/* Scoped styling: restore list markers/margins Tailwind's preflight
431	            strips, keep images from overflowing, mark the selected image, and
432	            honour reduced-motion for the open/minimize animation. */}
433	        <style>{`
434	          .nx-mail-editor ul { list-style: disc; padding-left: 1.5rem; margin: 0.25rem 0; }
435	          .nx-mail-editor ol { list-style: decimal; padding-left: 1.5rem; margin: 0.25rem 0; }
436	          .nx-mail-editor li { margin: 0.125rem 0; }
437	          .nx-mail-editor img { max-width: 100%; height: auto; border-radius: 0.375rem; cursor: pointer; }
438	          .nx-mail-editor img.nx-img-selected { outline: 2px solid #a89aff; outline-offset: 1px; }
439	          .nx-mail-editor a { color: #a89aff; text-decoration: underline; }
440	          @media (prefers-reduced-motion: reduce) {
441	            .nx-compose-panel, .nx-compose-dock { animation: none !important; transition: none !important; }
442	          }
443	        `}</style>
444	        <div
445	          className="nx-compose-panel glass pointer-events-auto relative flex h-[85vh] max-h-[85vh] w-full max-w-2xl flex-col overflow-hidden shadow-2xl animate-fade-up sm:h-auto"
446	          onClick={(e) => e.stopPropagation()}
447	          onDragEnter={(e) => {
448	            if (!e.dataTransfer?.types?.includes("Files")) return;
449	            e.preventDefault();
450	            dragDepth.current += 1;
451	            setDragging(true);
452	          }}
453	          onDragOver={(e) => {
454	            if (e.dataTransfer?.types?.includes("Files")) e.preventDefault();
455	          }}
456	          onDragLeave={() => {
457	            dragDepth.current = Math.max(0, dragDepth.current - 1);
458	            if (dragDepth.current === 0) setDragging(false);
459	          }}
460	          onDrop={onDrop}
461	        >
462	          {/* Drag-and-drop overlay */}
463	          {dragging && (
464	            <div className="pointer-events-none absolute inset-0 z-10 flex items-center justify-center bg-navy-950/80 backdrop-blur-sm">
465	              <div className="flex flex-col items-center gap-2 rounded-xl border-2 border-dashed border-brand-400/60 bg-white/[0.04] px-8 py-6 text-brand-200">
466	                <Icon.paperclip size={22} />
467	                <span className="text-sm font-medium">Drop files to attach</span>
468	              </div>
469	            </div>
470	          )}
471	
472	          {/* Header */}
473	          <div className="flex items-center justify-between border-b border-white/[0.08] bg-white/[0.03] px-5 py-3">
474	            <h3 className="flex items-center gap-2 text-sm font-semibold text-white">
475	              <span className="text-brand-300"><Icon.compose size={16} /></span>
476	              {title}
477	            </h3>
478	            <div className="flex items-center gap-1">
479	              <button onClick={onMinimize} className="btn-ghost rounded-lg p-1.5" aria-label="Minimize" title="Minimize">
480	                <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round">
481	                  <path d="M5 19h14" />
482	                </svg>
483	              </button>
484	              <button onClick={onClose} className="btn-ghost rounded-lg p-1.5" aria-label="Discard" title="Discard">
485	                <Icon.close size={16} />
486	              </button>
487	            </div>
488	          </div>
489	
490	          {/* Fields */}
491	          <div
492	            className="flex-1 overflow-y-auto"
493	            onScroll={() => {
494	              if (selectedImgRef.current) setImgRect(selectedImgRef.current.getBoundingClientRect());
495	            }}
496	          >
497	            <ChipField
498	              label="To"
499	              chips={toChips}
500	              input={toInput}
501	              inputRef={toInputRef}
502	              disabled={sending}
503	              placeholder="name@example.com"
504	              onInput={setToInput}
505	              onCommit={commitTo}
506	              onRemove={(addr) => setToChips((prev) => prev.filter((c) => c !== addr))}
507	              onBackspaceEmpty={() => setToChips((prev) => prev.slice(0, -1))}
508	              trailing={
509	                !showCc ? (
510	                  <button onClick={() => setShowCc(true)} className="ml-2 flex-none text-xs font-medium text-slate-500 hover:text-brand-300">
511	                    Cc
512	                  </button>
513	                ) : null
514	              }
515	            />
516	
517	            {showCc && (
518	              <ChipField
519	                label="Cc"
520	                chips={ccChips}
521	                input={ccInput}
522	                disabled={sending}
523	                placeholder="cc@example.com"
524	                onInput={setCcInput}
525	                onCommit={commitCc}
526	                onRemove={(addr) => setCcChips((prev) => prev.filter((c) => c !== addr))}
527	                onBackspaceEmpty={() => setCcChips((prev) => prev.slice(0, -1))}
528	              />
529	            )}
530	
531	            <FieldRow label="Subject">
532	              <input
533	                value={subject}
534	                onChange={(e) => setSubject(e.target.value)}
