./components/nx/ThemeToggle.tsx

"use client";

import { useEffect, useState } from "react";
import { Icon } from "./Icon";

/**
 * Dark / light switch.
 *
 * Writes `data-theme` on <html> and remembers the choice in localStorage. The
 * FIRST paint is handled by an inline script in app/layout.tsx, not by this
 * component — a React effect runs after hydration, which is one paint too late
 * and shows a white flash on every load for anyone on light.
 *
 * Dark is the default and stays the product's identity; light is opt-in. The
 * rail and top bar are dark in both (see `.nx-dark-island` in globals.css), so
 * this control always sits on a dark surface and does not need to restyle
 * itself when the theme flips.
 */

export const THEME_KEY = "nx-theme";

export function ThemeToggle() {
  const [light, setLight] = useState(false);

  /* Apply the stored preference on mount, then strip it on unmount.
   *
   * The inline script in app/layout.tsx only runs once, on the very first
   * document load — it never re-fires on a client-side route change, but
   * `<html>` is shared by the whole app (marketing and the dashboard render
   * inside the SAME root layout), so `data-theme` set here otherwise just
   * rides along on any soft navigation. This component only ever mounts
   * inside the dashboard shell, so its mount/unmount IS the "entered/left the
   * portal" signal: apply the saved choice when the customer lands here by
   * a client-side nav (the inline script had nothing to gate for this
   * specific route transition), and remove it the moment they navigate back
   * out, so marketing/login can never inherit a light theme they were never
   * built for — matching the inline script's own now-path-gated behavior.
   */
  useEffect(() => {
    let stored: string | null = null;
    try {
      stored = localStorage.getItem(THEME_KEY);
    } catch {
      /* Private mode or blocked storage — fail closed to dark. */
    }
    const isLight = stored === "light";
    setLight(isLight);
    const root = document.documentElement;
    if (isLight) root.setAttribute("data-theme", "light");
    return () => {
      root.removeAttribute("data-theme");
    };
  }, []);

  function toggle() {
    const next = !light;
    setLight(next);
    const root = document.documentElement;
    if (next) root.setAttribute("data-theme", "light");
    else root.removeAttribute("data-theme");
    try {
      localStorage.setItem(THEME_KEY, next ? "light" : "dark");
    } catch {
      /* Private mode or blocked storage. The theme still applies for this
         session; it just will not be remembered, which is the right failure. */
    }
  }

  return (
    <button
      type="button"
      onClick={toggle}
      role="switch"
      aria-checked={light}
      aria-label={light ? "Switch to dark theme" : "Switch to light theme"}
      title={light ? "Dark theme" : "Light theme"}
      className="grid h-10 w-10 place-items-center rounded-[10px] text-tx-dim transition hover:bg-[rgba(72,148,255,0.08)] hover:text-white"
    >
      {/* Sun when light is ON (click to go dark), moon when dark is ON (click
          to go light) — the icon names the theme you'd switch TO, matching
          how every other toggle in the shell reads. */}
      <Icon name={light ? "sun" : "moon"} size={18} tone="inherit" />
    </button>
  );
}
