"use client";

// TEMPORARY verification harness — not part of the app, not linked anywhere,
// deleted before this branch is submitted for review. Exists only so the
// Composer can be opened and screenshotted with Playwright without a live
// IMAP backend or database. Wraps in `.nx-shell-root` (the real class the
// portal-scoped Nexion token CSS keys off, via `:root:has(.nx-shell-root)`
// per app/globals.css) so the composer — portalled to document.body exactly
// like production — picks up the same tokens it would inside the real
// dashboard shell.

import { useState } from "react";
import { ComposeProvider, useCompose } from "@/components/customer/mail/ComposeProvider";
import type { ComposeDraft } from "@/components/customer/mail/Composer";

const REPLY_DRAFT: ComposeDraft = {
  mode: "reply",
  to: "customer@example.com",
  cc: "",
  subject: "Re: Invoice question",
  body: "",
  quotedHtml:
    "<p>Hi team,</p><p>Could you clarify the last invoice line item? Thanks!</p><p>— Jordan</p>",
  signature: "Nxeon Support",
  inReplyToUid: 1,
  replyFolder: "INBOX",
  sendMailboxAddress: "support@nxeon.cloud",
};

function Controls() {
  const { open, isOpen, isMinimized, minimize, restore } = useCompose();
  const [theme, setTheme] = useState<"dark" | "light">("dark");

  function toggleTheme() {
    const next = theme === "dark" ? "light" : "dark";
    setTheme(next);
    if (next === "light") document.documentElement.setAttribute("data-theme", "light");
    else document.documentElement.removeAttribute("data-theme");
  }

  return (
    <div className="flex flex-wrap gap-3 p-6">
      <button
        id="dp-open-reply"
        onClick={() => open({ ...REPLY_DRAFT })}
        className="btn-primary rounded-lg px-4 py-2"
      >
        Open reply
      </button>
      <button id="dp-toggle-theme" onClick={toggleTheme} className="btn-secondary rounded-lg px-4 py-2">
        Theme: {theme} (click to switch)
      </button>
      {isOpen && (
        <button
          id="dp-toggle-min"
          onClick={() => (isMinimized ? restore() : minimize())}
          className="btn-secondary rounded-lg px-4 py-2"
        >
          {isMinimized ? "Restore" : "Minimize"}
        </button>
      )}
      <span id="dp-state" data-open={isOpen} data-minimized={isMinimized} className="text-xs text-slate-500">
        state
      </span>
    </div>
  );
}

export default function DevPreviewMailComposer() {
  return (
    <div className="nx-shell-root min-h-screen bg-navy-950">
      <ComposeProvider>
        <Controls />
      </ComposeProvider>
    </div>
  );
}

