    const sel = (s) => document.querySelector(s);
    const grab = (el) => {
      if (!el) return null;
      const cs = getComputedStyle(el);
      return { bg: cs.backgroundColor, color: cs.color, borderColor: cs.borderColor, backdropFilter: cs.backdropFilter };
