=== find MessageCustomerButton.tsx ===
./components/admin/MessageCustomerButton.tsx

=== does it import/reuse Composer? ===
"use client";

import { useEffect, useState } from "react";
import { useActionState } from "react";
import { createPortal } from "react-dom";
import { useRouter } from "next/navigation";
import { startStaffDm } from "@/lib/actions-staff-dm";

/**
 * "Message customer" — the entry point for a staff-initiated direct message,
 * from the Customer 360 page (app/admin/users/[id]/page.tsx). Unlike the
 * ticket/chat controls this sits beside, it needs no existing thread to
 * attach to: a staff member can open this on ANY customer's profile with no
 * prior ticket or chat message on record, which is the entire point of a DM
 * versus a ticket (see prisma/schema.prisma's StaffDm doc comment).
 *
 * A centered modal (same backdrop pattern as components/admin/ExcludeIpPanel.tsx),
 * NOT an anchored dropdown — this used to be `position: absolute` off the
 * button, which pulls it out of document flow with nothing reserving space
 * below it, so it rendered floating directly on top of the very next card on
 * the page (Client info) instead of dimming/covering the page the way an
 * overlay should.
 *
 * PORTALED to document.body — the first fix (switching to `fixed inset-0`)
 * still rendered as a normal DOM child of this button's own `.card` ancestor
 * (the profile header), and `.card` applies `backdrop-blur-md`. A
 * `backdrop-filter` on an ancestor creates a new containing block for
 * `position: fixed` descendants (same as `transform`), so the "fixed"
 * overlay resolved against that CARD's box instead of the real viewport —
 * clipped at the card's edge instead of covering the page. Same class of bug
 * ExcludeIpPanel.tsx's own comment documents already hitting
 * AddFundsPaymentModal.tsx/ProvisioningOverlay.tsx; missed here because only
 * its backdrop/JSX shape was copied, not the portal that actually escapes it.
 */
export function MessageCustomerButton({ userId }: { userId: string }) {
  const router = useRouter();
  const [open, setOpen] = useState(false);
  const [state, action, pending] = useActionState(
    async (prev: { error?: string; dmId?: string }, fd: FormData) => startStaffDm(prev, fd),
    {} as { error?: string; dmId?: string },
  );

  useEffect(() => {
    if (state?.dmId) router.push(`/admin/dms/${state.dmId}`);
  }, [state?.dmId, router]);

  return (
    <>
      <button type="button" className="btn-secondary" onClick={() => setOpen(true)}>
        Message customer
      </button>
      {open &&
        createPortal(
          <div
            className="fixed inset-0 z-40 flex items-start justify-center overflow-y-auto bg-black/60 p-4 sm:p-8"
            onMouseDown={() => setOpen(false)}
          >
            <div
              className="my-4 w-full max-w-[24rem] rounded-2xl border border-white/10 bg-navy-900 p-4 shadow-2xl"
              onMouseDown={(e) => e.stopPropagation()}
            >
              <h3 className="mb-1 text-sm font-semibold text-slate-200">Direct message</h3>
              <p className="mb-3 text-xs text-slate-500">
                A lightweight note straight to this customer — not a support ticket. It shows up in
                their own &quot;Messages&quot; inbox, separate from their ticket history, and they can reply.
              </p>
              <form action={action} className="space-y-2.5">
                <input type="hidden" name="userId" value={userId} />
                <input
                  name="subject"
                  placeholder={'Subject (e.g. "Heads up about your server")'}
                  className="input w-full text-sm"
                  maxLength={150}
                  required
                />
                <textarea
                  name="body"
                  placeholder="Write your message…"
                  className="input min-h-24 w-full resize-y text-sm"
                  maxLength={10000}
                  required
                />
                <div className="flex items-center justify-end gap-2">
                  {state?.error && <span className="mr-auto text-xs text-red-400">{state.error}</span>}
                  <button type="button" className="btn-ghost px-3 py-1.5 text-xs" onClick={() => setOpen(false)} disabled={pending}>
                    Cancel
                  </button>
                  <button className="btn-primary px-3 py-1.5 text-xs" disabled={pending}>
                    {pending ? "Sending…" : "Send message"}
                  </button>
                </div>
              </form>
            </div>
          </div>,
          document.body,
        )}
    </>
  );
}

