import { chromium } from 'playwright';
const SHOTS = '/tmp/claude-0/-root/ec6fa978-d80b-4147-9982-eea470598e2c/scratchpad/shots';
const browser = await chromium.launch();
const page = await browser.newPage({ viewport: { width: 1280, height: 500 } });
await page.goto('http://localhost:3199/devpreview-mail-composer', { waitUntil: 'networkidle' });
await page.click('#dp-toggle-theme');
await page.waitForTimeout(200);
// Trigger the toast directly via the exposed handleSend path isn't wired to my harness UI;
// simulate visually by injecting the same markup ComposeProvider renders for the toast.
await page.evaluate(() => {
  const div = document.createElement('div');
  div.className = 'pointer-events-none fixed bottom-4 left-1/2 z-[70] -translate-x-1/2';
  div.innerHTML = '<div class="glass flex items-center gap-2 px-4 py-2.5 text-sm text-slate-100 shadow-2xl">Message sent.</div>';
  document.body.appendChild(div);
});
await page.waitForTimeout(200);
await page.screenshot({ path: `${SHOTS}/after-light-toast.png` });
await browser.close();
console.log('done');
EOF
